/*
 * A337936  Irregular triangle read by rows: row n gives the complete system
 *          of tripling sequences modulo N = floor((3*n-1)/2), for n >= 1.
 * https://oeis.org/A337936
 *
 * Offset:    1    (a(1) is the first term)
 * Keywords:  nonn, tabf, easy
 * Formula:   a(n) is the n‑th element of the irregular triangle read by rows.
 *            Row n consists of the complete system of tripling sequences
 *            modulo N(n) = ⌊(3n−1)/2⌋, written in order of seeds (starting
 *            from 1). The sequence is generated by traversing the rows in
 *            this manner
 * Range:     u8 n <= 110, u16 n <= 110, u32 n <= 110, u64 n <= 110,
 *            u128 n <= 110, big any n
 * Helpers:   gcd, mod_pow
 *
 * Sequence data from the OEIS (https://oeis.org), licensed CC BY-SA 4.0.
 */

#include <stdlib.h>
#include <stdint.h>
#include <stdbool.h>
#include "../utils/gcd.h"
#include "../utils/mod_pow.h"

/* Euler's totient function φ(m).  m ≤ floor((3n−1)/2). */
static seq_t compute_phi(idx_t m)
{
    seq_t phi = (seq_t)m;
    idx_t x   = m;
    for (idx_t p = 2; p * p <= x; ++p) {
        if (x % p == 0) {
            while (x % p == 0) x /= p;
            phi -= phi / p;
        }
    }
    if (x > 1) phi -= phi / x;
    return phi;
}

/* Multiplicative order of 3 modulo N (gcd(3,N)=1). */
static seq_t compute_order_3(idx_t N, seq_t phiN)
{
    seq_t   order = phiN;
    idx_t   temp  = (idx_t)phiN;   /* fits in idx_t because φ(N) ≤ N */

    for (idx_t p = 2; p * p <= temp; ++p) {
        if (temp % p == 0) {
            while (temp % p == 0) temp /= p;
            while (order % p == 0 &&
                   mod_pow((seq_t)3, (uint64_t)(order / p), (seq_t)N) == (seq_t)1)
                order /= p;
        }
    }
    if (temp > 1) {
        seq_t prime = (seq_t)temp;
        while (order % prime == 0 &&
               mod_pow((seq_t)3, (uint64_t)(order / prime), (seq_t)N) == (seq_t)1)
            order /= prime;
    }
    return order;
}

/* Main function required by the build. */
seq_t a(idx_t n)
{
    /* Find the row r containing index n. */
    idx_t  r          = 1;
    idx_t  cumulative = 0;

    while (1) {
        idx_t   N      = (3 * r - 1) / 2;          /* floor((3r−1)/2)   */
        seq_t   phiN   = compute_phi(N);
        idx_t   row_len = (idx_t)phiN;             /* length of row r     */
        if (cumulative + row_len >= n)            /* target row found   */
            break;
        cumulative += row_len;
        ++r;
    }

    idx_t  N  = (3 * r - 1) / 2;
    /* Special case N = 1 (row 1) */
    if (N == 1) return (seq_t)1;

    seq_t   phiN   = compute_phi(N);
    idx_t   row_len = (idx_t)phiN;
    idx_t   offset  = n - cumulative - 1;          /* 0‑based point in row */

    seq_t   order = compute_order_3(N, phiN);      /* cycle length (P(N)) */

    /* Allocate visited array to mark elements already placed in the row. */
    uint8_t *visited = (uint8_t *)calloc((size_t)N, 1);
    if (!visited) return (seq_t)0;                 /* safety check */

    idx_t pos = 0;                                 /* current position in row */

    for (idx_t s = 1; s < N; ++s) {
        if (gcd((seq_t)s, (seq_t)N) != (seq_t)1) continue;  /* s not in RRS(N) */
        if (visited[(size_t)s]) continue;                        /* already seeded */

        seq_t val = (seq_t)s;
        for (idx_t j = 0; j < (idx_t)order; ++j) {
            if (pos == offset) {                /* found the answer */
                free(visited);
                return val;
            }
            visited[(size_t)val] = 1;
            ++pos;
            val = (val * 3) % (seq_t)N;
        }
    }

    free(visited);                                 /* should never reach */
    return (seq_t)0;
}
